// ─── useReviewScorecardData.ts ────────────────────────────────────────────────
// Custom hook that owns ALL data-fetching for the Review Scorecard detail view.
// Mirrors every useEffect / fetch call in the old HodViewScorecard.tsx.

import { useState, useEffect, useCallback } from "react";
import { CandidateScoreCardData, CommentsData, InterviewedLevelValue, OverallScoreRow, QuestionScoreRow } from "../services/IScorecardService";
import { QuestionItem } from "../../SelectionProcess/services/QuestionnaireApi/IQuestionnaireApi";
import { AutoCompleteItem } from "../../SelectionProcess/CommonServices/CommonServices";
import {
  buildOverallScoreRows,
  fetchCandidateDetail,
  fetchGradeLevel,
  getPanelLevelTitles,
  fetchScoreData,
  fetchPositionOptions,
  fetchSelectedCandidateDetails,
  fetchComments,
  fetchQuestionnaire,
} from "../services/ScorecardApiService";
import { StatusId } from "../../../../utilities/Config";


const TODAY = new Date();

const DEFAULT_CANDIDATE: CandidateScoreCardData = {
  CandidateID: 0,
  RecruitmentID: 0,
  JobCode: "",
  JobCodeId: 0,
  PassportID: "",
  FristName: "",
  MiddleName: "",
  LastName: "",
  FullName: "",
  ResidentialAddress: "",
  DOB: "",
  ContactNumber: "",
  Email: "",
  Nationality: "",
  Gender: "",
  TotalYearOfExperiance: "",
  Skills: "",
  LanguageKnown: "",
  ReleventExperience: "",
  Qualification: "",
  Qualifications: { key: 0, text: "" },
  Experience: { key: 0, text: "" },
  Knowledge: { key: 0, text: "" },
  Energylevel: { key: 0, text: "" },
  Requirements: { key: 0, text: "" },
  contributeculture: { key: 0, text: "" },
  ExpatExperienceCongolese: { key: 0, text: "" },
  CriteriaRecognised: { key: 0, text: "" },
  CandidateCVDoc: [],
  Employment: "",
  EvaluationFeedback: "",
  OverAllEvaluationFeedback: "",
  SignDate: new Date(
    TODAY.getFullYear(),
    TODAY.getMonth(),
    TODAY.getDate(),
    TODAY.getHours(),
    TODAY.getMinutes(),
    TODAY.getSeconds(),
  ),
  AdvertisementDocument: [],
  RoleProfileDocument: [],
  PositionTitle: "",
  InterviewDate: "",
  interviewPanelTitles: [],
  JobRequestID: "",
  Comments: "",
  ExternalAgentName: "",
  JobGrade: "",
  InterviewLevels: [],
  GPA: "",
  ConflictsOfInterest: "",
  disability: "",
  disabilityReason: "",
};

interface UseReviewScorecardDataOptions {
  candidateID: number;
  recruitmentID: number;
  jobCodeID: number | string;
  department: string;
  statusId: number;
  employeeList: any[];
}

export function useReviewScorecardData({
  candidateID,
  recruitmentID,
  jobCodeID,
  department,
  statusId,
  employeeList,
}: UseReviewScorecardDataOptions) {
  const [candidateData, setCandidateData] =
    useState<CandidateScoreCardData>(DEFAULT_CANDIDATE);
  const [interviewedLevel, setInterviewedLevel] =
    useState<InterviewedLevelValue>({ Levels: "", Grade: "" });
  const [panelLevel1, setPanelLevel1] = useState<string[]>([]);
  const [panelLevel2, setPanelLevel2] = useState<string[]>([]);
  const [rawScores, setRawScores] = useState<any[]>([]);
  const [questionRows, setQuestionRows] = useState<QuestionScoreRow[]>([]);
  const [overallRows, setOverallRows] = useState<OverallScoreRow[]>([]);
  const [comments, setComments] = useState<{ level1: CommentsData[]; level2: CommentsData[] }>({
    level1: [],
    level2: [],
  });
  const [questionnaire, setQuestionnaire] = useState<QuestionItem[]>([]);
  const [positionOptions, setPositionOptions] = useState<AutoCompleteItem[]>([]);
  const [selectedPosition, setSelectedPosition] = useState<AutoCompleteItem | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  // ── Main fetch (candidate detail + panels + scores) ─────────────────────
  const loadAll = useCallback(async () => {
    if (!candidateID) return;
    setIsLoading(true);
    try {
      const [detail, level, panels, scores] = await Promise.all([
        fetchCandidateDetail(candidateID, employeeList),
        fetchGradeLevel(recruitmentID),
        getPanelLevelTitles(candidateID, employeeList),
        fetchScoreData(candidateID, employeeList),
      ] as const);

      setCandidateData((prev) => ({ ...prev, ...detail }));
      setInterviewedLevel(level);
      setPanelLevel1(panels.level1);
      setPanelLevel2(panels.level2);
      setRawScores(scores.rawScores);
      setQuestionRows(scores.questionRows);
      setOverallRows(buildOverallScoreRows(scores.rawScores));
    } catch (err) {
      console.error("useReviewScorecardData – loadAll error:", err);
    } finally {
      setIsLoading(false);
    }
  }, [candidateID, recruitmentID, employeeList]);

  useEffect(() => {
    void loadAll();
  }, [loadAll]);

  // ── Position options (when relevant status) ──────────────────────────────
  useEffect(() => {
    const needsPositionData = [
      StatusId.PendingwithHODtoAssignPositionID,
      StatusId.PendingwithHODtoselectthecandidate,
      StatusId.Selected,
      StatusId.OnHoldbyHOD,
      StatusId.CandidateOnHoldbyHODLevel2,
    ].includes(statusId);

    if (needsPositionData) {
      void fetchPositionOptions(jobCodeID, department).then(setPositionOptions);
    }
  }, [statusId, jobCodeID, department]);

  // ── Pre-fill selected position (when StatusId.Selected) ─────────────────
  useEffect(() => {
    if (statusId === StatusId.Selected && candidateID) {
      fetchSelectedCandidateDetails(candidateID).then((res) => {
        if (res) {
          setSelectedPosition({ key: res.positionValue, text: res.positionId });
        }
      });
    }
  }, [candidateID, statusId]);

  // ── Open comments view ───────────────────────────────────────────────────
  const loadComments = useCallback(async () => {
    const data = await fetchComments(candidateID, employeeList);
    setComments(data);
  }, [candidateID, employeeList]);

  // ── Load questionnaire ────────────────────────────────────────────────────
  const loadQuestionnaire = useCallback(async () => {
    const res = await fetchQuestionnaire(jobCodeID as number);
    if (res.status === 200) setQuestionnaire(res.data ?? []);
    return res.status;
  }, [jobCodeID]);

  // ── Update candidateData.Comments from outside ───────────────────────────
  const setComments_ = (value: string) =>
    setCandidateData((prev) => ({ ...prev, Comments: value }));

  return {
    candidateData,
    setCandidateData,
    interviewedLevel,
    panelLevel1,
    panelLevel2,
    rawScores,
    questionRows,
    overallRows,
    comments,
    questionnaire,
    positionOptions,
    selectedPosition,
    setSelectedPosition,
    isLoading,
    setIsLoading,
    loadComments,
    loadQuestionnaire,
    setCommentsText: setComments_,
    reload: loadAll,
  };
}